Ext.define('BNK.view.Budget.bgx.com.BgxItmCpnt54MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxItmCpnt54MViewController',

    config: {
        viewId: 'BgxItmCpnt54M'
    },

    /* 배정받은 코드들만 들고 온다.[DEFFERED] */
    fnSelectAssignedCodeList: function(param, isAssigned) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            D = new Ext.Deferred();

        var actgDt = vm.get('expItemInputData.bsnsDt');
        var bsnsYy = DateUtils.getFormatValue(new Date(DateUtils.parseDate(actgDt)), 'Y'); //사업연도
        var actgQut = DateUtils.getQuarter(new Date(DateUtils.parseDate(actgDt))); //회계분기
        param['hrHrpmCompId'] = SecurityUtils.getPrincipal().hrHrpmCompId;
        param['bsnsYy'] = bsnsYy;
        param['bgDvcd1'] = Constants.bgDvcd1.EXPN;
        param['isAsnQut'+actgQut] = isAssigned;
        param['bgNfcmAplYn'] = Constants.yesNo.YES;
        param['asnTrnsDvcd'] = Constants.asnTrnsDvcd.TOTAL_AMOUNT;
        param['criYy'] = bsnsYy; //인력배정에서 필요한 기준연도
        param['criDate'] = actgDt; //인력배정에서 필요한 기준일자.

        //TODO: 예산한도 같이 들고 와야 함. 화면에 뿌려줘야 해서.
        Ext.Ajax.request({
            headers : {
                serviceId : 'BgxNfmSvc.findAllExpItemCodeList',
                viewId : me.getViewId()
            },
            jsonData : param,
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);
                D.resolve(res.codeList);
            },
            failure : function(response, scope) {
                var res = Ext.JSON.decode(response.responseText);
                console.log('status: ' + res.status);
                console.log('statusText: ' + res.statusText);
                console.log('responseText: ' + res.responseText);

                D.reject(res.result);
            }

        });

        return D.promise;
    },

    /* 사용자 폼 추가 */
    onContainerAdd: function(container, item, index, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        // 집계
        vm.set('tct', Number(vm.get('tct'))+1);
        switch (item.getViewModel().data.data.stfDvcd) {
            case Constants.stfDvcd.IN :
            vm.set('innerEmpeCnt', Number(vm.get('innerEmpeCnt'))+1);
            break;
            case Constants.stfDvcd.OUT :
            vm.set('outerEmpeCnt', Number(vm.get('outerEmpeCnt'))+1);
            break;
        }
    },

    /* 사용자 폼 삭제 */
    onContainerRemove: function(container, item, index, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            userList = vm.get('userList');

        // del userData
        var userList = {},
            data = item.getViewModel().data.data,
            len = 0;
        for(var i in vm.get('userList')) {
            var tmp = vm.get('userList')[i];
            if (!(tmp.bgBudcBsnsId == data.bgBudcBsnsId && tmp.bsnsNm == data.bsnsNm && tmp.bsnsYy == data.bsnsYy && tmp.dpnm == data.dpnm && tmp.enpnm == data.enpnm && tmp.stfNm == data.stfNm && tmp.stfNo == data.stfNo)) {
                userList[len] = tmp;
                len++;
            }
        }
        vm.set('userList', userList);

        // 집계
        vm.set('tct', Number(vm.get('tct'))-1);
        switch (data.stfDvcd) {
            case Constants.stfDvcd.IN :
            vm.set('innerEmpeCnt', Number(vm.get('innerEmpeCnt'))-1);
            break;
            case Constants.stfDvcd.OUT :
            vm.set('outerEmpeCnt', Number(vm.get('outerEmpeCnt'))-1);
            break;
        }
    },

    /* 닫기 */
    onBtnClose: function(button, e, eOpts) {
        this.getView().close();
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            config = component.config;

        if (config && config.param) {
            var pViewData = config.param,
                expItemInputData = pViewData.expItemInputData;

            if (!pViewData || !pViewData.expItemInputData) {
                me.onBtnClose();
            }

            vm.set('expItemInputData', expItemInputData);
            vm.set('readOnlyFlag', pViewData.readOnlyFlag);

            // 사용자
            if (pViewData.expItemInputData.expItemUserInfo) {
                var userInfos = pViewData.expItemInputData.expItemUserInfo,
                    userList = [],
                    innerEmpeCnt = 0,
                    outerEmpeCnt = 0,
                    param = {
                        codeDvcdLists : ['BSNS_ASN'] //예산과목(배정받은 것)
                    };

                me.fnSelectAssignedCodeList(param, true).then(function(codeList){
                    var bsnsCodeList = codeList.bsnsCodeAsnList;

                    for(var i in userInfos) {
                        var bsnsNm = '',
                            bsnsId = userInfos[i].bgBudcBsnsId;

                        // 사업부문
                        for (var j in bsnsCodeList) {
                            if (bsnsCodeList[j].bgBudcBsnsId == bsnsId) {
                                bsnsNm = bsnsCodeList[j].bsnsNm;
                            }
                        }
                        userInfos[i].bsnsNm = bsnsNm;

                        userList.push(userInfos[i]);
                        refs.userCnt.add(Ext.create('BgxNfmAply52MItems', {
                            data : userInfos[i],
                            readOnlyFlag : vm.get('readOnlyFlag')
                        }));
                        switch (userInfos[i].stfDvcd) {
                            case Constants.stfDvcd.IN :
                            innerEmpeCnt++;
                            break;
                            case Constants.stfDvcd.OUT :
                            outerEmpeCnt++;
                            break;
                        }
                    }

                    // 계정과목
                    if (expItemInputData.xpnitKeyNm) {
                        refs.xpnitKeyNm.setValue(expItemInputData.xpnitKeyNm);
                    }

                    vm.set('userList', userList);
                    vm.set('tct', userInfos.length);
                    vm.set('innerEmpeCnt', innerEmpeCnt);
                    vm.set('outerEmpeCnt', outerEmpeCnt);
                });
            } else {
                vm.set('tct', 0);
                vm.set('innerEmpeCnt', 0);
                vm.set('outerEmpeCnt', 0);
            }

        }
    }

});